import { useQuery } from 'urql';

const USERS_QUERY = `
  query Users {
    users { id title }
  }
`;

export function UserListQuery() {
  const [result] = useQuery<{ users: { id: string; title: string }[] }>({{ query: USERS_QUERY }});
  if (result.fetching) return <p className="text-sm text-gray-500">Loading…</p>;
  if (result.error) return <p role="alert" className="text-red-600 text-sm">{result.error.message}</p>;
  return (
    <ul className="divide-y rounded border">
      {result.data?.users.map((row) => (
        <li key={row.id} className="px-3 py-2 text-sm">{row.title}</li>
      ))}
    </ul>
  );
}

'use client';

import { useEffect, useRef } from 'react';

export function Modal6({ open, onClose, children }: { open: boolean; onClose: () => void; children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    document.addEventListener('keydown', onKey);
    ref.current?.focus();
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <div role="dialog" aria-modal="true" aria-labelledby="modal-title-6" className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div ref={ref} tabIndex={-1} className="w-full max-w-lg rounded-lg bg-white p-6 shadow-xl">
        <h2 id="modal-title-6" className="text-lg font-semibold">Modal 6</h2>
        {children}
        <button type="button" onClick={onClose} className="mt-4 rounded border px-3 py-1 text-sm">Close</button>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(false);

  useEffect(() => {
    const mql = window.matchMedia(query);
    setMatches(mql.matches);
    const handler = (e: MediaQueryListEvent) => setMatches(e.matches);
    mql.addEventListener('change', handler);
    return () => mql.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

