import { useState, useRef, type KeyboardEvent } from 'react';

interface Tab {
  id: string;
  label: string;
  content: React.ReactNode;
}

interface TabsProps {
  tabs: Tab[];
  defaultTab?: string;
}

export function Tabs({ tabs, defaultTab }: TabsProps) {
  const [activeId, setActiveId] = useState(defaultTab ?? tabs[0]?.id ?? '');
  const tabRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  function handleKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    const ids = tabs.map((t) => t.id);
    const currentIdx = ids.indexOf(activeId);

    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      e.preventDefault();
      const next = ids[(currentIdx + 1) % ids.length];
      setActiveId(next);
      tabRefs.current.get(next)?.focus();
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      e.preventDefault();
      const prev = ids[(currentIdx - 1 + ids.length) % ids.length];
      setActiveId(prev);
      tabRefs.current.get(prev)?.focus();
    } else if (e.key === 'Home') {
      e.preventDefault();
      setActiveId(ids[0]);
      tabRefs.current.get(ids[0])?.focus();
    } else if (e.key === 'End') {
      e.preventDefault();
      const last = ids[ids.length - 1];
      setActiveId(last);
      tabRefs.current.get(last)?.focus();
    }
  }

  return (
    <div>
      <div role="tablist" onKeyDown={handleKeyDown} aria-label="Tabs">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            role="tab"
            id={`tab-${tab.id}`}
            aria-selected={activeId === tab.id}
            aria-controls={`panel-${tab.id}`}
            tabIndex={activeId === tab.id ? 0 : -1}
            ref={(el) => { if (el) tabRefs.current.set(tab.id, el); }}
            onClick={() => setActiveId(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      {tabs.map((tab) => (
        <div
          key={tab.id}
          role="tabpanel"
          id={`panel-${tab.id}`}
          aria-labelledby={`tab-${tab.id}`}
          hidden={activeId !== tab.id}
          tabIndex={0}
        >
          {tab.content}
        </div>
      ))}
    </div>
  );
}

